#define main DDLApplicationMain
#import "../Sources/App.m"
#undef main
#import "../Sources/SSCourseWindow.m"
static NSUInteger checks;
static void Check(BOOL ok,NSString *message){checks++;if(!ok){fprintf(stderr,"FAIL: %s\n",message.UTF8String);exit(1);}}
int main(){@autoreleasepool{[NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyProhibited];AppDelegate *app=AppDelegate.new;NSApp.delegate=app;[app applicationDidFinishLaunching:[NSNotification notificationWithName:NSApplicationDidFinishLaunchingNotification object:NSApp]];Check(NSApp.appearance==nil && app.window.appearance==nil,@"production launch inherits system appearance");
 NSButton *route=NSButton.new;route.tag=2;[app navigate:route];NSDictionary *task=app.tasks.firstObject;NSButton *selection=NSButton.new;selection.identifier=task[@"id"];[app selectTask:selection];[app editTask:selection];Check(app.editor!=nil,@"task editor opens while no course operation owns the task");EditorController *editor=app.editor;editor.notesField.string=@"Draft must survive style changes\\nSecond line";[editor.window makeFirstResponder:editor.notesField];editor.notesField.selectedRange=NSMakeRange(6,4);NSView *content=app.root;NSString *selected=app.selectedTaskID;NSPoint scroll=app.scroll.contentView.bounds.origin;
 for(NSString *appearance in @[NSAppearanceNameDarkAqua,NSAppearanceNameAqua]){NSApp.appearance=[NSAppearance appearanceNamed:appearance];[app refreshAppearance];Check(app.editor==editor && app.root==content && [app.selectedTaskID isEqual:selected] && NSEqualPoints(app.scroll.contentView.bounds.origin,scroll),@"restyling retains editor, content, task selection and scroll");Check([editor.notesField.string hasPrefix:@"Draft must survive"] && NSEqualRanges(editor.notesField.selectedRange,NSMakeRange(6,4)) && editor.window.firstResponder==editor.notesField,@"draft, caret selection and focus survive restyling");}
 Check(app.window.contentViewController==app.mainSplit && app.navigationItem.behavior==NSSplitViewItemBehaviorSidebar && app.sidebar.fill==nil,@"native split-view sidebar owns its system material without an opaque overlay");
 if(@available(macOS 26.0,*)){Check(Button(@"Primary",nil,NULL,1).bezelStyle==(NSBezelStyle)16 && Button(@"Secondary",nil,NULL,0).bezelStyle==NSBezelStyleRounded,@"primary action uses glass while secondary action keeps standard styling");ThemeSegmentedControl *tabs=Segments(@[@"Today",@"Week"],nil,NULL);Check(tabs.segmentStyle==NSSegmentStyleAutomatic && [[tabs valueForKey:@"borderShape"] integerValue]==1,@"segmented navigation uses automatic native styling and capsule shape");if(@available(macOS 27.0,*))Check([[tabs valueForKey:@"role"] integerValue]==1,@"segmented navigation declares its public tab role");}
 AMShowOperations(app.window);NSWindow *operations=nil;for(NSWindow *window in NSApp.windows)if([window.title isEqual:@"后台任务"])operations=window;NSString *operation=AMOperationBegin(@"Synthetic pending operation",@"Test",NO,nil);[NSRunLoop.mainRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.1]];Check([[(NSScrollView *)[operations valueForKey:@"operationScroll"] documentView] subviews].count>0,@"open background panel receives newly started operations");AMOperationFinish(operation,@"success",@"Synthetic complete");[operations orderOut:nil];
 NSApp.appearance=nil;[app.window endSheet:editor.window];[editor.window orderOut:nil];app.editor=nil;[app.window orderOut:nil];printf("PASS: %lu appearance inheritance and draft assertions\n",(unsigned long)checks);
}return 0;}
